"""Candidate coefficients are computed from sourced inputs, never generated by an LLM."""

import math
from datetime import date, timedelta
from typing import Any

from ...field_shift.schemas import Field as FieldSnapshot
from .contracts import InitialWater, SoilWater
from .inputs import PlanningDraft
from .model import Candidate, DailyResource, PeriodResource, PlanningField, Suitability
from .profiles import ProfileV3
from .science import prepare_growth

COEFFICIENT_RECIPE = "sourced-site-growth-economics-exposure-operations-v3.0"


def candidate_id(field_id: str, crop_id: str, sow: date) -> str:
    return f"{field_id}:{crop_id}:{sow.isoformat()}"


def make_candidate(
    *,
    draft: PlanningDraft,
    profile: ProfileV3,
    field: FieldSnapshot,
    planning_field: PlanningField,
    crop_id: str,
    sow: date,
    weather: dict[date, dict[str, Any]],
    daily_resources: list[DailyResource],
    period_resources: list[PeriodResource],
    baseline: bool,
) -> dict[str, Any]:
    crop = profile.crops[crop_id]
    conditions = draft.field_conditions[field.id]
    values: dict[str, Any] = {str(k): v.value for k, v in conditions.values.items()}
    rejected = []
    if crop_id in conditions.forbidden_crop_ids:
        rejected.append("crop_prohibited")
    if not any(first <= sow.strftime("%m-%d") <= last for first, last in crop.sow_windows):
        rejected.append("outside_sowing_window")
    if not (
        field.soil_texture in crop.soil.allowed_textures
        and crop.soil.ph_min <= values["ph"] <= crop.soil.ph_max
        and values["depth_m"] >= crop.soil.min_depth_m
        and values["salinity_ds_m"] <= crop.soil.max_salinity_ds_m
        and values["drainage"] in crop.soil.allowed_drainage
    ):
        rejected.append("soil_unsuitable")
    if (
        values["slope_deg"] > crop.soil.max_slope_deg
        or values["aspect"] not in crop.soil.allowed_aspects
        or values["terrain_position"] not in crop.soil.allowed_terrain_positions
    ):
        rejected.append("terrain_unsuitable")
    if not values["mechanical_access"]:
        rejected.append("mechanical_access_unavailable")
    for history in planning_field.history:
        gap = (sow - history.end_latest).days - history.turnaround_days - 1
        if gap < 0 or history.family == crop.family and gap < profile.family_gaps[crop.family]:
            rejected.append("historical_gap")
    if rejected:
        return {"candidate": None, "reasons": sorted(set(rejected))}
    soil = SoilWater(**{key: values[key] for key in ("field_capacity", "wilting_point", "depth_m")})
    initial = InitialWater(
        policy=values["initial_water_policy"],
        confirmed=True,
        evidence_id="input:" + conditions.values["initial_water_policy"].source_ids[0],
    )
    growth = prepare_growth(
        phenology=crop.phenology,
        canopy=crop.canopy,
        soil=soil,
        initial=initial,
        sow=sow,
        end=draft.end,
        weather=weather,
        effective_rain_fraction=values["effective_rain_fraction"],
    )
    if growth["reason"] is not None:
        return {"candidate": None, "reasons": [growth["reason"]]}
    harvest = growth["harvest_date"]
    count = growth["growing_days"]
    rows = [weather[sow + timedelta(days=i)] for i in range(count)]
    daylight = []
    for i in range(count):
        day = sow + timedelta(days=i)
        declination = 0.409 * math.sin(2 * math.pi * day.timetuple().tm_yday / 365 - 1.39)
        hour_angle = math.acos(
            max(-1.0, min(1.0, -math.tan(math.radians(field.latitude)) * math.tan(declination)))
        )
        daylight.append(24 / math.pi * hour_angle)
    demand = sum(row["etc_mm"] for row in growth["trace"]["water_days"])
    components = {
        "heat": sum(row["tmax_c"] > crop.climate.heat_c for row in rows) / count,
        "frost": sum(row["tmin_c"] < crop.climate.frost_c for row in rows) / count,
        "excess_rain": sum(row["rain_mm"] > crop.climate.excess_rain_mm for row in rows) / count,
        "irrigation_dependence": min(1.0, sum(growth["water_mm"]) / demand)
        if demand > 0
        else float(any(growth["water_mm"])),
    }
    if (
        components["heat"] > crop.climate.max_heat_fraction
        or components["frost"] > crop.climate.max_frost_fraction
        or components["excess_rain"] > crop.climate.max_excess_fraction
        or min(daylight) < crop.climate.min_daylight_h
        or max(daylight) > crop.climate.max_daylight_h
    ):
        rejected.append("climate_unsuitable")
    if not field.irrigation_available and any(value > 1e-6 for value in growth["water_mm"]):
        rejected.append("irrigation_unavailable")
    operations: dict[str, dict[date, float]] = {}
    farm = draft.farm_resources[planning_field.farm_id]
    for operation in crop.operations:
        identifier = next(
            key
            for key, r in farm.daily.items()
            if r.kind == "machine"
            and r.machine_type == operation.machine
            and field.id in r.field_ids
        )
        day = (sow if operation.anchor == "sow" else harvest) + timedelta(
            days=operation.offset_days
        )
        if day > growth["occupied_until"]:
            rejected.append("operation_outside_occupancy")
            continue
        schedule = operations.setdefault(identifier, {})
        schedule[day] = schedule.get(day, 0.0) + operation.hours_ha
    for resource in daily_resources:
        if field.id not in resource.field_ids:
            continue
        if resource.kind == "water":
            demand_by_day = {
                sow + timedelta(days=i): field.area_ha * 10 * v
                for i, v in enumerate(growth["water_mm"])
            }
        else:
            demand_by_day = {
                day: field.area_ha * v for day, v in operations.get(resource.id, {}).items()
            }
        if any(
            not resource.days[day].remediable and amount > resource.days[day].capacity + 1e-6
            for day, amount in demand_by_day.items()
        ):
            rejected.append("hard_" + resource.kind + "_capacity")
    for period_limit in period_resources:
        if period_limit.farm_id != planning_field.farm_id or period_limit.crop_id != crop_id:
            continue
        event = sow if period_limit.kind == "seed" else harvest
        period = next(p for p in draft.periods if p.id == period_limit.period_id)
        amount = field.area_ha * (
            crop.seed_kg_ha if period_limit.kind == "seed" else crop.yield_kg_ha
        )
        if (
            period.start <= event <= period.end
            and not period_limit.limit.remediable
            and amount > period_limit.limit.capacity + 1e-6
        ):
            rejected.append("hard_" + period_limit.kind + "_capacity")
    if rejected:
        return {"candidate": None, "reasons": sorted(set(rejected))}
    economics = crop.economics
    profit = (
        None
        if "profit" in draft.disabled_metrics
        else crop.yield_kg_ha * economics.price_usd_kg - economics.cost_usd_ha
        if economics
        else None
    )
    soil_score = (
        None
        if "soil" in draft.disabled_metrics
        else sum(
            value * getattr(crop.soil_weights, key)
            for key, value in crop.soil_components.model_dump().items()
        )
        if crop.soil_components and crop.soil_weights
        else None
    )
    risk = (
        None
        if "risk" in draft.disabled_metrics
        else sum(value * getattr(crop.risk_weights, key) for key, value in components.items())
        if crop.risk_weights
        else None
    )
    candidate = Candidate(
        id=candidate_id(field.id, crop_id, sow),
        field_id=field.id,
        crop_id=crop_id,
        species_id=crop.species_id,
        family=crop.family,
        sow_date=sow,
        harvest_date=harvest,
        turnaround_days=crop.phenology.turnaround_days,
        water_mm=growth["water_mm"],
        cover_mask=growth["cover_mask"],
        seed_kg_ha=crop.seed_kg_ha,
        yield_kg_ha=crop.yield_kg_ha,
        profit_usd_ha=profit,
        soil_score=soil_score,
        risk_score=risk,
        machine_hours_ha=operations,
        suitability=Suitability(sow=True, soil=True, terrain=True, climate=True, management=True),
        baseline_confirmed=baseline,
    )
    return {
        "candidate": candidate,
        "reasons": [],
        "trace": {
            "recipe": COEFFICIENT_RECIPE,
            "growth": growth,
            "risk": {
                "components": components,
                "min_daylight_h": min(daylight),
                "max_daylight_h": max(daylight),
                "interpretation": (
                    "historical exposure and irrigation dependence, not yield-loss probability"
                ),
            },
            "field_version": field.version,
            "profile_id": profile.id,
            "crop_id": crop_id,
            "soil_components": crop.soil_components.model_dump() if crop.soil_components else None,
            "economics": economics.model_dump() if economics else None,
            "operating_evidence": conditions.model_dump(mode="json"),
        },
    }
